function SectionTitle({ eyebrow, title, detail, action }: { eyebrow: string; title: string; detail: string; action?: React.ReactNode }) {
  return <div className="mb-7 flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between">
    <div>
      <div className="mb-2 flex items-center gap-2 font-mono-app text-[10px] font-medium uppercase tracking-[.2em] text-primary"><span className="h-1.5 w-1.5 rounded-full bg-primary pulse-dot" />{eyebrow}</div>
      <h1 className="font-display text-3xl font-bold tracking-[-.04em] text-foreground sm:text-4xl">{title}</h1>
      <p className="mt-2 max-w-xl text-sm leading-6 text-muted-foreground">{detail}</p>
    </div>
    {action}
  </div>;
}

function IconBadge({ icon: Icon, color = 'purple' }: { icon: LucideIcon; color?: 'purple' | 'teal' | 'gold' | 'red' }) {
  const styles = { purple: 'bg-[#ede9ff] text-primary', teal: 'bg-[#dff3f0] text-[#197a74]', gold: 'bg-[#fff0cf] text-[#9e6a0d]', red: 'bg-[#fce2de] text-[#b83c32]' };
  return <div className={`flex h-9 w-9 shrink-0 items-center justify-center rounded-xl ${styles[color]}`}><Icon className="h-4 w-4" /></div>;
}

function StatCard({ label, value, change, icon: Icon, accent = 'purple', children }: { label: string; value: string; change?: string; icon: LucideIcon; accent?: 'purple' | 'teal' | 'gold'; children?: React.ReactNode }) {
  const tint = accent === 'gold' ? 'bg-[#fff4d9]' : accent === 'teal' ? 'bg-[#def3ef]' : 'bg-[#ede9ff]';
  const color = accent === 'gold' ? 'text-[#9a6610]' : accent === 'teal' ? 'text-[#1e8179]' : 'text-primary';
  return <div className="card-lift rounded-2xl border border-card-border bg-card p-5 shadow-sm">
    <div className="flex items-start justify-between"><div><p className="text-xs font-medium text-muted-foreground">{label}</p><p className="mt-2 font-display text-2xl font-bold tracking-[-.05em]">{value}</p></div><div className={`flex h-10 w-10 items-center justify-center rounded-xl ${tint} ${color}`}><Icon className="h-[18px] w-[18px]" /></div></div>
    {change && <p className={`mt-4 text-xs font-medium ${color}`}>{change}</p>}{children}
  </div>;
}

function ActionButton({ children, onClick, variant = 'primary', icon: Icon, className = '', disabled = false, testId }: { children: React.ReactNode; onClick?: () => void; variant?: 'primary' | 'soft' | 'outline' | 'danger'; icon?: LucideIcon; className?: string; disabled?: boolean; testId?: string }) {
  const styles = { primary: 'bg-primary text-primary-foreground shadow-[0_5px_0_hsl(259_58%_45%)] hover:shadow-[0_3px_0_hsl(259_58%_45%)]', soft: 'bg-[#ede9ff] text-primary hover:bg-[#e4ddff]', outline: 'border border-border bg-card text-foreground hover:border-primary/50', danger: 'bg-[#fce2de] text-[#a63d34] hover:bg-[#f8d4cf]' };
  return <button data-testid={testId ?? "button-action"} disabled={disabled} onClick={onClick} className={`button-pop inline-flex items-center justify-center gap-2 rounded-xl px-4 py-2.5 text-sm font-semibold transition disabled:cursor-not-allowed disabled:opacity-45 ${styles[variant]} ${className}`}>{Icon && <Icon className="h-4 w-4" />}{children}</button>;
}

function ConnectionPill() {
  const { data, isLoading } = useGetDiscordStatus({
    query: {
      queryKey: getGetDiscordStatusQueryKey(),
      staleTime: 30_000,
      retry: false,
    },
  });
  const connected = data?.connected === true;
  const loading = isLoading && !data;
  return <div data-testid="status-discord-connection" title={data?.message ?? 'Checking Discord connection'} className={`flex items-center gap-2 rounded-full border px-3 py-1.5 text-[11px] font-medium ${connected ? 'border-[#b6e1da] bg-[#e6f7f4] text-[#236e68]' : 'border-[#efd8a8] bg-[#fff7e4] text-[#895e16]'}`}><span className={`h-1.5 w-1.5 rounded-full ${loading ? 'bg-[#d99228] pulse-dot' : connected ? 'bg-secondary' : 'bg-[#d99228]'}`} />{loading ? 'Checking Discord' : connected ? `${data.botName ?? 'Discord bot'} connected` : 'Demo mode'} <span className={`hidden sm:inline ${connected ? 'text-[#5a9d97]' : 'text-[#ad823d]'}`}>· {connected ? `${data.guildCount} server${data.guildCount === 1 ? '' : 's'}` : 'Discord not connected'}</span></div>;
}

