function Economy({ balance, bank, setBalance, setBank, inventory, setInventory, addActivity }: { balance: number; bank: number; setBalance: (v: number) => void; setBank: (v: number) => void; inventory: InventoryItem[]; setInventory: (v: InventoryItem[]) => void; addActivity: (a: Omit<ActivityItem, 'id' | 'time'>) => void }) {
  const [amount, setAmount] = useState('500');
  const [notice, setNotice] = useState('');
  const transact = (kind: 'deposit' | 'withdraw') => { const n = Math.max(0, Number(amount) || 0); if (!n) return; if (kind === 'deposit' && n <= balance) { setBalance(balance - n); setBank(bank + n); setNotice(`${money(n)} moved into your bank.`); addActivity({ type: 'spend', title: 'Deposited credits', detail: 'Moved from wallet to bank', amount: `-${money(n)}` }); } else if (kind === 'withdraw' && n <= bank) { setBalance(balance + n); setBank(bank - n); setNotice(`${money(n)} withdrawn to your wallet.`); addActivity({ type: 'earn', title: 'Withdrew credits', detail: 'Moved from bank to wallet', amount: `+${money(n)}` }); } else setNotice('That amount is not available right now.'); };
  const buy = (item: InventoryItem) => { if (balance < item.price) { setNotice('Not enough credits for that drop.'); return; } setBalance(balance - item.price); setInventory(inventory.map(i => i.id === item.id ? { ...i, count: i.count + 1 } : i)); setNotice(`${item.name} landed in your inventory.`); addActivity({ type: 'spend', title: `Bought a ${item.name}`, detail: 'Added to your collection', amount: `-${money(item.price)}` }); };
  return <><Header title="Economy" /><SectionTitle eyebrow="The exchange" title="Credits make the world go round." detail="Earn, stash, spend, repeat. Nothing here is precious except the fun." action={<div className="rounded-xl bg-[#fff4d9] px-3 py-2 font-mono-app text-[10px] text-[#8f6317]">market pulse <span className="ml-1 text-[#1e8179]">+4.8%</span></div>} />
    {notice && <div data-testid="status-economy-notice" className="mb-5 flex items-center gap-2 rounded-xl border border-[#b6e1da] bg-[#e6f7f4] px-4 py-3 text-sm text-[#236e68]"><Check className="h-4 w-4" />{notice}<button data-testid="button-dismiss-notice" onClick={() => setNotice('')} className="ml-auto"><X className="h-4 w-4" /></button></div>}
    <div className="grid gap-4 sm:grid-cols-2"><StatCard label="Available to spend" value={money(balance)} change="Ready for the next impulse buy" icon={Coins} /><StatCard label="Safe in the bank" value={money(bank)} change="2.4% daily interest rate" icon={LockKeyhole} accent="teal" /></div>
    <div className="mt-5 grid gap-5 xl:grid-cols-[.75fr_1.25fr]"><div className="rounded-2xl border border-card-border bg-card p-5 shadow-sm"><h2 className="font-display text-lg font-bold">Move your credits</h2><p className="mt-1 text-xs leading-5 text-muted-foreground">Keep your wallet nimble or let your bank grow quietly.</p><div className="mt-5"><label className="text-xs font-semibold text-muted-foreground">Amount</label><div className="mt-2 flex items-center rounded-xl border border-input bg-background px-3 focus-within:border-primary"><Coins className="h-4 w-4 text-accent" /><input data-testid="input-transfer-amount" type="number" value={amount} onChange={e => setAmount(e.target.value)} className="w-full bg-transparent px-2 py-3 font-mono-app text-sm outline-none" /><span className="text-xs text-muted-foreground">credits</span></div></div><div className="mt-3 grid grid-cols-2 gap-2"><ActionButton data-testid="button-deposit" icon={ArrowDownToLine} onClick={() => transact('deposit')}>Deposit</ActionButton><ActionButton icon={ArrowUpFromLine} variant="outline" onClick={() => transact('withdraw')}>Withdraw</ActionButton></div><div className="mt-5 flex gap-2">{[100, 500, 1000].map(n => <button data-testid={`button-amount-${n}`} key={n} onClick={() => setAmount(String(n))} className="flex-1 rounded-lg border border-border py-2 text-[10px] font-semibold text-muted-foreground transition hover:border-primary hover:text-primary">{n} c</button>)}</div></div>
      <div className="rounded-2xl border border-card-border bg-card p-5 shadow-sm"><div className="mb-5 flex items-end justify-between"><div><h2 className="font-display text-lg font-bold">The drop shelf</h2><p className="mt-1 text-xs text-muted-foreground">Limited community-made goods · refreshes Sunday</p></div><button data-testid="button-shop-info" className="rounded-lg p-2 text-muted-foreground hover:bg-muted hover:text-primary"><CircleHelp className="h-4 w-4" /></button></div><div className="grid gap-3 sm:grid-cols-3">{inventory.map(item => <div data-testid={`card-shop-item-${item.id}`} key={item.id} className="card-lift relative overflow-hidden rounded-xl border border-border bg-background p-4"><div className="mb-4 flex h-16 items-center justify-center rounded-lg" style={{ background: `${item.color}18` }}><item.icon className="h-8 w-8" style={{ color: item.color }} /></div><p className="text-sm font-bold">{item.name}</p><p className="mt-1 min-h-[34px] text-[10px] leading-4 text-muted-foreground">{item.description}</p><div className="mt-4 flex items-center justify-between"><span className="font-mono-app text-xs text-[#a7711d]">{money(item.price)}</span><button data-testid={`button-buy-${item.id}`} onClick={() => buy(item)} className="rounded-lg bg-primary px-2.5 py-1.5 text-[10px] font-bold text-primary-foreground transition hover:brightness-110">Buy</button></div></div>)}</div></div></div>
    <div className="mt-5 rounded-2xl border border-card-border bg-card p-5 shadow-sm"><div className="mb-4 flex items-center justify-between"><div><h2 className="font-display text-lg font-bold">Your inventory</h2><p className="mt-1 text-xs text-muted-foreground">Things you have collected along the way.</p></div><Package className="h-5 w-5 text-secondary" /></div><div className="flex flex-wrap gap-3">{inventory.map(item => <div data-testid={`inventory-item-${item.id}`} key={item.id} className="flex items-center gap-3 rounded-xl border border-border bg-background px-3 py-2.5"><div className="flex h-8 w-8 items-center justify-center rounded-lg" style={{ background: `${item.color}18`, color: item.color }}><item.icon className="h-4 w-4" /></div><div><p className="text-xs font-semibold">{item.name}</p><p className="font-mono-app text-[10px] text-muted-foreground">quantity {item.count}</p></div></div>)}</div></div>
  </>;
}

function Games({ balance, setBalance, addActivity }: { balance: number; setBalance: (v: number) => void; addActivity: (a: Omit<ActivityItem, 'id' | 'time'>) => void }) {
  const [game, setGame] = useState('coin');
  const [result, setResult] = useState('Pick a game and make your move.');
  const [question, setQuestion] = useState(0);
  const games = [{ id: 'coin', label: 'Coin flip', icon: Coins, description: 'Call it. Double it.', color: 'gold' as const }, { id: 'trivia', label: 'Trivia', icon: CircleHelp, description: 'Know your server lore?', color: 'purple' as const }, { id: 'word', label: 'Word scramble', icon: MessageSquare, description: 'Untangle the letters.', color: 'teal' as const }, { id: 'math', label: 'Math challenge', icon: BarChart3, description: 'Quick brain, quick credits.', color: 'red' as const }, { id: 'rps', label: 'Rock paper scissors', icon: Swords, description: 'Classic showdown.', color: 'purple' as const }];
  const play = (choice?: string) => { let win = false; let text = ''; if (game === 'coin') { const outcome = Math.random() > .5 ? 'Heads' : 'Tails'; win = choice === outcome.toLowerCase(); text = `${outcome}. ${win ? 'You called it — +100 credits.' : 'The coin had other plans.'}`; } if (game === 'trivia') { win = choice === 'B'; text = win ? 'Correct. The server remembers — +150 credits.' : 'Not quite. The answer was B — the night shift.'; } if (game === 'word') { win = choice?.toLowerCase() === 'arcade'; text = win ? 'Unjumbled. +180 credits.' : 'The word was ARCADE. Give it another spin.'; } if (game === 'math') { win = choice === '42'; text = win ? 'Clean solve. +120 credits.' : 'Not this time. The answer was 42.'; } if (game === 'rps') { const bot = ['rock', 'paper', 'scissors'][Math.floor(Math.random() * 3)]; win = choice === bot ? false : (choice === 'rock' && bot === 'scissors') || (choice === 'paper' && bot === 'rock') || (choice === 'scissors' && bot === 'paper'); text = `${bot} beats your ${choice}. ${choice === bot ? 'Draw — no change.' : win ? 'You win — +100 credits.' : 'Better luck next round.'}`; } setResult(text); if (win) { setBalance(balance + (game === 'trivia' ? 150 : game === 'word' ? 180 : game === 'math' ? 120 : 100)); addActivity({ type: 'game', title: `Won ${games.find(g => g.id === game)?.label}`, detail: 'A tidy win in the arcade', amount: `+${game === 'trivia' ? 150 : game === 'word' ? 180 : game === 'math' ? 120 : 100} c` }); } setQuestion(question + 1); };
  const current = games.find(g => g.id === game)!;
  return <><Header title="Arcade" /><SectionTitle eyebrow="Play for keeps" title="Five ways to get lucky." detail="Short games, real rewards, absolutely no pressure. Unless someone is watching." action={<div className="flex items-center gap-2 rounded-xl border border-border bg-card px-3 py-2"><Coins className="h-4 w-4 text-accent" /><span className="font-mono-app text-xs">{money(balance)}</span></div>} />
    <div className="grid gap-5 xl:grid-cols-[.82fr_1.18fr]"><div className="rounded-2xl border border-card-border bg-card p-4 shadow-sm"><p className="mb-3 px-2 font-mono-app text-[10px] uppercase tracking-[.16em] text-muted-foreground">Choose your cabinet</p>{games.map(g => <button data-testid={`button-game-${g.id}`} onClick={() => { setGame(g.id); setResult('Pick an answer to make your move.'); }} key={g.id} className={`mb-2 flex w-full items-center gap-3 rounded-xl border p-3 text-left transition ${game === g.id ? 'border-primary/35 bg-[#f3efff]' : 'border-transparent hover:border-border hover:bg-muted/50'}`}><IconBadge icon={g.icon} color={g.color} /><div className="flex-1"><p className="text-sm font-bold">{g.label}</p><p className="mt-0.5 text-[11px] text-muted-foreground">{g.description}</p></div>{game === g.id && <Check className="h-4 w-4 text-primary" />}</button>)}</div>
      <div className="grid-paper relative overflow-hidden rounded-2xl border border-card-border bg-[#f8f3ea] p-6 shadow-sm sm:p-8"><div className="absolute -right-10 -top-12 h-36 w-36 rounded-full bg-accent/20 blur-2xl" /><div className="relative flex items-center justify-between"><div><p className="font-mono-app text-[10px] uppercase tracking-[.2em] text-primary">Cabinet 0{games.findIndex(g => g.id === game) + 1}</p><h2 className="mt-2 font-display text-2xl font-bold tracking-[-.05em]">{current.label}</h2></div><div className="rounded-lg bg-sidebar px-3 py-2 font-mono-app text-[10px] text-accent">round {String(question + 1).padStart(2, '0')}</div></div><div className="relative mt-8 min-h-[250px] rounded-2xl border-2 border-dashed border-primary/20 bg-card/80 p-5"><p className="text-sm font-semibold">{game === 'coin' ? 'Call the coin.' : game === 'trivia' ? 'Which channel has the best late-night lore?' : game === 'word' ? 'Unscramble: D E C A R A' : game === 'math' ? 'Solve: 6 × 7 = ?' : 'Choose your champion.'}</p>{game === 'trivia' && <p className="mt-3 text-xs text-muted-foreground">A · #general &nbsp; B · #night-shift &nbsp; C · #rules</p>}{game === 'word' && <p className="mt-4 font-mono-app text-2xl font-bold tracking-[.3em] text-primary">D E C A R A</p>}{game === 'math' && <p className="mt-4 font-display text-4xl font-bold text-primary">6 × 7 = ?</p>}<div className="mt-8 flex flex-wrap gap-2">{(game === 'coin' ? ['heads', 'tails'] : game === 'trivia' ? ['A', 'B', 'C'] : game === 'word' ? ['arcade', 'decade', 'cared'] : game === 'math' ? ['36', '42', '48'] : ['rock', 'paper', 'scissors']).map(choice => <button data-testid={`button-choice-${choice}`} onClick={() => play(choice)} key={choice} className="button-pop rounded-xl border border-primary/20 bg-[#ede9ff] px-4 py-2.5 text-xs font-bold capitalize text-primary hover:bg-primary hover:text-primary-foreground">{choice}</button>)}</div></div><div data-testid="text-game-result" className="relative mt-4 flex items-start gap-2 rounded-xl bg-sidebar px-4 py-3 text-xs leading-5 text-sidebar-foreground"><Sparkles className="mt-0.5 h-4 w-4 shrink-0 text-accent" />{result}</div></div></div>
  </>;
}

function MemeStudio({ addActivity }: { addActivity: (a: Omit<ActivityItem, 'id' | 'time'>) => void }) {
  const templates = [{ id: 'late', label: 'Late night server', top: 'WHEN THE SERVER SAYS', bottom: 'ONE MORE GAME', bg: 'linear-gradient(135deg,#332257,#7463d9)' }, { id: 'tiny', label: 'Tiny achievement', top: 'ME AFTER', bottom: 'CLAIMING 250 CREDITS', bg: 'linear-gradient(135deg,#196b72,#52b9aa)' }, { id: 'boss', label: 'Final boss', top: 'MODS LOG ON', bottom: 'THE CHAT GETS QUIET', bg: 'linear-gradient(135deg,#c06a3b,#f1b750)' }];
  const [template, setTemplate] = useState(templates[0]); const [top, setTop] = useState(template.top); const [bottom, setBottom] = useState(template.bottom); const [treatment, setTreatment] = useState('clean'); const [saved, setSaved] = useState(false);
  const choose = (t: typeof templates[number]) => { setTemplate(t); setTop(t.top); setBottom(t.bottom); setSaved(false); };
  const save = () => { setSaved(true); addActivity({ type: 'meme', title: 'Saved a meme creation', detail: `${template.label} template`, amount: '+ style points' }); };
  return <><Header title="Meme studio" /><SectionTitle eyebrow="Make something loud" title="Turn server lore into poster art." detail="Pick a format, add the quote everyone will recognize, and send it back into the chat." action={<ActionButton icon={Plus} onClick={() => { setTop(''); setBottom(''); setSaved(false); }}>New canvas</ActionButton>} />
    <div className="grid gap-5 xl:grid-cols-[.72fr_1.28fr]"><div className="space-y-5"><div className="rounded-2xl border border-card-border bg-card p-5 shadow-sm"><div className="mb-4 flex items-center justify-between"><h2 className="font-display text-lg font-bold">Choose a template</h2><span className="font-mono-app text-[10px] text-muted-foreground">{templates.length} live</span></div><div className="space-y-2">{templates.map(t => <button data-testid={`button-template-${t.id}`} onClick={() => choose(t)} key={t.id} className={`flex w-full items-center gap-3 rounded-xl border p-2 text-left transition ${template.id === t.id ? 'border-primary/40 bg-[#f3efff]' : 'border-transparent hover:border-border'}`}><div className="h-12 w-16 rounded-lg" style={{ background: t.bg }} /><div className="flex-1"><p className="text-xs font-bold">{t.label}</p><p className="mt-1 text-[10px] text-muted-foreground">{t.top} · {t.bottom}</p></div>{template.id === t.id && <Check className="h-4 w-4 text-primary" />}</button>)}</div></div><div className="rounded-2xl border border-card-border bg-card p-5 shadow-sm"><h2 className="font-display text-lg font-bold">Write the punchline</h2><div className="mt-4 space-y-3"><label className="block text-xs font-semibold text-muted-foreground">Top text<input data-testid="input-meme-top" value={top} onChange={e => setTop(e.target.value.toUpperCase())} className="mt-2 w-full rounded-xl border border-input bg-background px-3 py-3 text-xs font-bold outline-none transition focus:border-primary" /></label><label className="block text-xs font-semibold text-muted-foreground">Bottom text<input data-testid="input-meme-bottom" value={bottom} onChange={e => setBottom(e.target.value.toUpperCase())} className="mt-2 w-full rounded-xl border border-input bg-background px-3 py-3 text-xs font-bold outline-none transition focus:border-primary" /></label></div><div className="mt-5"><p className="text-xs font-semibold text-muted-foreground">Treatment</p><div className="mt-2 grid grid-cols-3 gap-2">{['clean', 'grain', 'mono'].map(item => <button data-testid={`button-treatment-${item}`} onClick={() => setTreatment(item)} key={item} className={`rounded-lg border py-2 text-[10px] font-bold capitalize transition ${treatment === item ? 'border-primary bg-[#ede9ff] text-primary' : 'border-border text-muted-foreground'}`}>{item}</button>)}</div></div></div></div>
      <div className={`relative flex min-h-[560px] flex-col rounded-2xl border border-card-border bg-card p-5 shadow-sm ${treatment === 'mono' ? 'grayscale' : ''}`}><div className="mb-5 flex items-center justify-between"><div><h2 className="font-display text-lg font-bold">Preview</h2><p className="mt-1 text-xs text-muted-foreground">Asteria’s latest masterpiece, probably.</p></div><div className="flex items-center gap-2"><button data-testid="button-meme-download" className="rounded-lg border border-border p-2 text-muted-foreground hover:text-primary"><ArrowDownToLine className="h-4 w-4" /></button><button data-testid="button-meme-share" onClick={save} className="rounded-lg border border-border p-2 text-muted-foreground hover:text-primary"><ArrowUpFromLine className="h-4 w-4" /></button></div></div><div data-testid="meme-preview" className={`relative m-auto flex aspect-square w-full max-w-[460px] flex-col justify-between overflow-hidden rounded-2xl p-6 text-center shadow-lg sm:p-9 ${treatment === 'grain' ? 'noise' : ''}`} style={{ background: template.bg }}><div className="absolute inset-0 opacity-15" style={{ backgroundImage: 'radial-gradient(circle at 20% 20%,#fff 0 1px,transparent 1px)', backgroundSize: '13px 13px' }} /><p className="relative font-display text-2xl font-extrabold leading-[.98] tracking-[-.06em] text-white drop-shadow-[2px_3px_0_rgba(37,22,63,.35)] sm:text-4xl">{top || 'YOUR TOP TEXT'}</p><div className="relative flex flex-1 items-center justify-center"><div className="h-24 w-24 rotate-6 rounded-[30%] border-4 border-white/50 bg-white/20 shadow-xl"><div className="mt-7 text-4xl text-white"><Bot className="mx-auto h-10 w-10" /></div></div></div><p className="relative font-display text-2xl font-extrabold leading-[.98] tracking-[-.06em] text-white drop-shadow-[2px_3px_0_rgba(37,22,63,.35)] sm:text-4xl">{bottom || 'YOUR BOTTOM TEXT'}</p></div><div className="mt-5 flex items-center justify-between rounded-xl bg-muted/55 px-4 py-3"><p className="text-xs text-muted-foreground">{saved ? 'Saved to your creations.' : 'Looks good? Put it in the chat.'}</p><ActionButton onClick={save} variant="soft" icon={saved ? Check : ArrowUpFromLine}>{saved ? 'Saved' : 'Save & share'}</ActionButton></div></div></div>
  </>;
}

