function Leaderboards() {
  const [tab, setTab] = useState('balance');
  const tabs = [{ id: 'balance', label: 'Balance', icon: Coins }, { id: 'inventory', label: 'Inventory value', icon: Package }, { id: 'achievements', label: 'Achievements', icon: Trophy }];
  return <><Header title="Leaderboards" /><SectionTitle eyebrow="The hall of fame" title="A little friendly pressure." detail="See who is hoarding credits, collecting the rarest drops, and showing up for the community." action={<div className="flex items-center gap-2 rounded-xl bg-[#ede9ff] px-3 py-2 text-xs font-semibold text-primary"><Crown className="h-4 w-4" />Season 04</div>} /><div className="mb-5 flex gap-2 overflow-x-auto rounded-xl border border-card-border bg-card p-2 shadow-sm">{tabs.map(t => <button data-testid={`button-leaderboard-${t.id}`} key={t.id} onClick={() => setTab(t.id)} className={`flex shrink-0 items-center gap-2 rounded-lg px-4 py-2.5 text-xs font-semibold transition ${tab === t.id ? 'bg-sidebar text-sidebar-foreground' : 'text-muted-foreground hover:bg-muted'}`}><t.icon className="h-4 w-4" />{t.label}</button>)}</div><div className="grid gap-5 xl:grid-cols-[.8fr_1.2fr]"><div className="rounded-2xl border border-card-border bg-card p-6 text-center shadow-sm"><div className="mx-auto flex h-24 w-24 items-center justify-center rounded-full border-8 border-[#eee7ff] bg-primary font-display text-3xl font-bold text-white">4</div><p className="mt-5 font-display text-xl font-bold">That’s your spot</p><p className="mt-2 text-sm leading-6 text-muted-foreground">You’re 6,560 credits behind pixelbloom. One good week at the arcade could change that.</p><div className="mt-6 flex items-center justify-center gap-6"><div><p className="font-display text-xl font-bold">12,680</p><p className="text-[10px] uppercase tracking-wider text-muted-foreground">credits</p></div><div className="h-8 w-px bg-border" /><div><p className="font-display text-xl font-bold">1,240</p><p className="text-[10px] uppercase tracking-wider text-muted-foreground">to next rank</p></div></div></div><div className="rounded-2xl border border-card-border bg-card p-5 shadow-sm"><div className="mb-4 flex items-center justify-between"><div><h2 className="font-display text-lg font-bold">{tabs.find(t => t.id === tab)?.label} rankings</h2><p className="mt-1 text-xs text-muted-foreground">Moonbeam Arcade · all members</p></div><button data-testid="button-refresh-rankings" className="rounded-lg p-2 text-muted-foreground hover:bg-muted hover:text-primary"><RefreshCw className="h-4 w-4" /></button></div>{leaderboard.concat([{ rank: 5, name: 'moth.exe', initials: 'ME', value: '10,875 c', tone: 'bg-[#e1d7cb] text-[#654d38]' }]).map((person, i) => <div data-testid={`leaderboard-row-${person.rank}`} key={person.rank} className={`flex items-center gap-3 rounded-xl px-3 py-3 ${person.name === 'you' ? 'bg-[#f3efff]' : ''}`}><span className="w-5 text-center font-mono-app text-xs text-muted-foreground">{person.rank}</span><div className={`flex h-9 w-9 items-center justify-center rounded-xl text-[10px] font-bold ${person.tone}`}>{person.initials}</div><div className="flex-1"><p className="text-sm font-bold">{person.name}</p><p className="text-[10px] text-muted-foreground">{i === 0 ? 'unstoppable' : i === 3 ? 'that’s you' : 'active this week'}</p></div><p className="font-mono-app text-xs font-medium">{tab === 'achievements' ? `${[28, 24, 19, 16, 14][i]} badges` : tab === 'inventory' ? `${[8460, 7210, 5890, 4120, 3670][i].toLocaleString()} c` : person.value}</p></div>)}</div></div></>;
}

function Moderation({ activities, addActivity }: { activities: ActivityItem[]; addActivity: (a: Omit<ActivityItem, 'id' | 'time'>) => void }) {
  const [notice, setNotice] = useState('');
  const act = (title: string, detail: string) => { addActivity({ type: 'mod', title, detail }); setNotice(`${title} logged to the moderation stream.`); };
  return <><Header title="Moderation" /><SectionTitle eyebrow="Keep the room good" title="The quiet power tools." detail="A healthy server is a lively one. These controls are safe demo actions until Discord is connected." action={<div className="flex items-center gap-2 rounded-xl border border-[#b6e1da] bg-[#e6f7f4] px-3 py-2 text-xs font-semibold text-[#236e68]"><span className="h-1.5 w-1.5 rounded-full bg-secondary" />All systems calm</div>} />{notice && <div data-testid="status-moderation-notice" className="mb-5 flex items-center gap-2 rounded-xl bg-sidebar px-4 py-3 text-sm text-sidebar-foreground"><Check className="h-4 w-4 text-accent" />{notice}<button onClick={() => setNotice('')} className="ml-auto text-sidebar-foreground/50"><X className="h-4 w-4" /></button></div>}<div className="grid gap-5 xl:grid-cols-[.85fr_1.15fr]"><div className="rounded-2xl border border-card-border bg-card p-5 shadow-sm"><h2 className="font-display text-lg font-bold">Demo controls</h2><p className="mt-1 text-xs leading-5 text-muted-foreground">Try a safe action. It will appear in the activity stream.</p><div className="mt-5 space-y-2">{[{ label: 'Ban a member', detail: 'Remove from the server', icon: Ban, action: () => act('Member banned', 'demo-user was removed from Moonbeam Arcade'), tone: 'danger' }, { label: 'Kick a member', detail: 'Send them back to the lobby', icon: UserRound, action: () => act('Member kicked', 'quiet-orbit was sent to the lobby'), tone: 'soft' }, { label: 'Lock a channel', detail: 'Pause messages in a channel', icon: LockKeyhole, action: () => act('Channel locked', '#announcements is read-only'), tone: 'soft' }, { label: 'Unlock a channel', detail: 'Let the conversation flow', icon: Hash, action: () => act('Channel unlocked', '#announcements is open again'), tone: 'soft' }].map(item => <button data-testid={`button-mod-${item.label.toLowerCase().replaceAll(' ', '-')}`} onClick={item.action} key={item.label} className="group flex w-full items-center gap-3 rounded-xl border border-border p-3 text-left transition hover:border-primary/25 hover:bg-muted/50"><IconBadge icon={item.icon} color={item.tone === 'danger' ? 'red' : 'purple'} /><div className="flex-1"><p className="text-sm font-bold">{item.label}</p><p className="mt-1 text-[10px] text-muted-foreground">{item.detail}</p></div><ChevronRight className="h-4 w-4 text-muted-foreground transition group-hover:translate-x-1 group-hover:text-primary" /></button>)}</div></div><div className="rounded-2xl border border-card-border bg-card p-5 shadow-sm"><div className="mb-4 flex items-center justify-between"><div><h2 className="font-display text-lg font-bold">Moderation stream</h2><p className="mt-1 text-xs text-muted-foreground">Most recent activity across the server</p></div><Shield className="h-5 w-5 text-secondary" /></div><ActivityFeed items={activities.filter(a => a.type === 'mod')} /></div></div></>;
}

function Settings({ settings, setSettings }: { settings: ServerSettings; setSettings: (s: ServerSettings) => void }) {
  const [saved, setSaved] = useState(false);
  const toggle = (key: string) => setSettings({ ...settings, toggles: { ...settings.toggles, [key]: !settings.toggles[key] } });
  const save = () => setSaved(true);
  return <><Header title="Server settings" /><SectionTitle eyebrow="Tune the machine" title="Make the bot sound like you." detail="A few dials shape the mood of Moonbeam Arcade. Changes are saved in this demo session." action={saved ? <div className="flex items-center gap-2 text-xs font-semibold text-secondary"><Check className="h-4 w-4" />Saved just now</div> : <ActionButton icon={Check} onClick={save}>Save changes</ActionButton>} /><div className="grid gap-5 xl:grid-cols-[1.1fr_.9fr]"><div className="rounded-2xl border border-card-border bg-card p-5 shadow-sm sm:p-6"><h2 className="font-display text-lg font-bold">Server personality</h2><p className="mt-1 text-xs text-muted-foreground">The small details members feel every day.</p><div className="mt-6 grid gap-5 sm:grid-cols-2"><label className="block text-xs font-semibold">Command prefix<span className="mt-2 flex items-center rounded-xl border border-input bg-background px-3 focus-within:border-primary"><span className="font-mono-app text-primary">/</span><input data-testid="input-prefix" value={settings.prefix} onChange={e => { setSaved(false); setSettings({ ...settings, prefix: e.target.value }); }} className="w-full bg-transparent px-2 py-3 font-mono-app text-sm outline-none" /></span><span className="mt-1 block text-[10px] font-normal text-muted-foreground">How members wake Arcade Command up.</span></label><label className="block text-xs font-semibold">Bank interest rate<span className="mt-2 flex items-center rounded-xl border border-input bg-background px-3 focus-within:border-primary"><input data-testid="input-interest" type="number" value={settings.interest} onChange={e => { setSaved(false); setSettings({ ...settings, interest: Number(e.target.value) }); }} className="w-full bg-transparent py-3 font-mono-app text-sm outline-none" /><span className="font-mono-app text-xs text-muted-foreground">%</span></span><span className="mt-1 block text-[10px] font-normal text-muted-foreground">Applied each daily reset.</span></label><label className="block text-xs font-semibold">Shop price mood<span className="mt-2 flex items-center rounded-xl border border-input bg-background px-3 focus-within:border-primary"><input data-testid="input-shop-markup" type="number" value={settings.shopMarkup} onChange={e => { setSaved(false); setSettings({ ...settings, shopMarkup: Number(e.target.value) }); }} className="w-full bg-transparent py-3 font-mono-app text-sm outline-none" /><span className="font-mono-app text-xs text-muted-foreground">%</span></span><span className="mt-1 block text-[10px] font-normal text-muted-foreground">A little scarcity keeps the shelf interesting.</span></label></div></div><div className="rounded-2xl border border-card-border bg-card p-5 shadow-sm sm:p-6"><h2 className="font-display text-lg font-bold">Command toggles</h2><p className="mt-1 text-xs text-muted-foreground">Choose what is visible to your community.</p><div className="mt-5 space-y-1">{Object.entries(settings.toggles).map(([key, value]) => <div key={key} className="flex items-center gap-3 border-b border-border/70 py-3 last:border-0"><div className="flex h-8 w-8 items-center justify-center rounded-lg bg-[#ede9ff] text-primary"><Command className="h-4 w-4" /></div><p className="flex-1 text-sm font-semibold">{key}</p><button data-testid={`button-toggle-${key}`} onClick={() => toggle(key)} className={`relative h-6 w-11 rounded-full transition ${value ? 'bg-secondary' : 'bg-muted'}`}><span className={`absolute top-1 h-4 w-4 rounded-full bg-white shadow-sm transition-transform ${value ? 'translate-x-6' : 'translate-x-1'}`} /></button></div>)}</div></div></div><div className="mt-5 rounded-2xl bg-sidebar p-5 text-sidebar-foreground sm:p-6"><div className="flex flex-col gap-4 sm:flex-row sm:items-center"><div className="flex h-11 w-11 items-center justify-center rounded-xl bg-accent text-accent-foreground"><Bot className="h-5 w-5" /></div><div className="flex-1"><p className="font-display text-base font-bold">Discord is still outside the door.</p><p className="mt-1 text-xs text-sidebar-foreground/60">These controls are remembered for your session. Connect later to make them real.</p></div><ActionButton variant="soft" onClick={() => setSaved(true)}>Keep demo state</ActionButton></div></div></>;
}

function Help() {
  const [search, setSearch] = useState('');
  const commands = [{ command: '/daily', category: 'Economy', description: 'Claim your daily credits and keep your streak alive.', usage: '/daily' }, { command: '/balance', category: 'Economy', description: 'Peek at your wallet and bank total.', usage: '/balance' }, { command: '/flip', category: 'Games', description: 'Call heads or tails for a chance to double your bet.', usage: '/flip heads 50' }, { command: '/shop', category: 'Economy', description: 'Browse the latest drops on the community shelf.', usage: '/shop' }, { command: '/meme', category: 'Community', description: 'Open a meme template with server-ready text.', usage: '/meme' }, { command: '/leaderboard', category: 'Community', description: 'See who is leading the season across three rankings.', usage: '/leaderboard balance' }, { command: '/lock', category: 'Moderation', description: 'Pause a channel when the room needs a breath.', usage: '/lock #channel' }, { command: '/settings', category: 'Configure', description: 'Review your server’s Arcade Command preferences.', usage: '/settings' }];
  const filtered = commands.filter(c => `${c.command} ${c.category} ${c.description}`.toLowerCase().includes(search.toLowerCase()));
  return <><Header title="Command index" /><SectionTitle eyebrow="Your field guide" title="Everything starts with a command." detail="Search the index, then send the one-liner to your server when Discord is connected." action={<div className="flex items-center gap-2 rounded-xl bg-[#e6f7f4] px-3 py-2 text-xs font-semibold text-[#236e68]"><Check className="h-4 w-4" />8 commands ready</div>} /><div className="grid gap-5 xl:grid-cols-[1.2fr_.8fr]"><div className="rounded-2xl border border-card-border bg-card p-5 shadow-sm"><div className="relative mb-5"><Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" /><input data-testid="input-command-search" value={search} onChange={e => setSearch(e.target.value)} placeholder="Search commands, categories, or what they do..." className="w-full rounded-xl border border-input bg-background py-3 pl-10 pr-4 text-sm outline-none focus:border-primary" /></div><div className="space-y-2">{filtered.map(command => <div data-testid={`command-row-${command.command.slice(1)}`} key={command.command} className="group rounded-xl border border-transparent p-3 transition hover:border-border hover:bg-muted/50"><div className="flex items-start gap-3"><div className="rounded-lg bg-[#ede9ff] px-2 py-1 font-mono-app text-xs font-medium text-primary">{command.command}</div><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><p className="text-sm font-bold">{command.category}</p><span className="rounded-full bg-muted px-2 py-0.5 text-[9px] font-semibold text-muted-foreground">{command.usage}</span></div><p className="mt-1 text-xs leading-5 text-muted-foreground">{command.description}</p></div><button data-testid={`button-copy-${command.command.slice(1)}`} className="rounded-lg p-2 text-muted-foreground opacity-0 transition hover:bg-card hover:text-primary group-hover:opacity-100"><Plus className="h-4 w-4 rotate-45" /></button></div></div>)}</div>{filtered.length === 0 && <div className="py-12 text-center"><Search className="mx-auto h-8 w-8 text-muted-foreground/40" /><p className="mt-3 text-sm font-semibold">No commands in that corner.</p><p className="mt-1 text-xs text-muted-foreground">Try a shorter search.</p></div>}</div><div className="space-y-5"><div className="rounded-2xl border border-card-border bg-card p-5 shadow-sm"><div className="flex items-center gap-3"><div className="flex h-10 w-10 items-center justify-center rounded-xl bg-accent text-accent-foreground"><Bot className="h-5 w-5" /></div><div><h2 className="font-display text-lg font-bold">New here?</h2><p className="text-xs text-muted-foreground">You’re in the right room.</p></div></div><div className="mt-5 space-y-4">{[['01', 'Claim your first reward', 'Start with /daily and set the rhythm.'], ['02', 'Try the arcade', 'A little trivia never hurt anyone.'], ['03', 'Make the chat yours', 'Turn an inside joke into a meme.']].map(step => <div key={step[0]} className="flex gap-3"><span className="font-mono-app text-xs text-primary">{step[0]}</span><div><p className="text-sm font-semibold">{step[1]}</p><p className="mt-1 text-xs leading-5 text-muted-foreground">{step[2]}</p></div></div>)}</div></div><div className="rounded-2xl border border-[#e9d6ad] bg-[#fff7e4] p-5"><div className="flex gap-3"><div className="flex h-8 w-8 shrink-0 items-center justify-center rounded-lg bg-[#f8e7bd] text-[#9a6916]"><Bell className="h-4 w-4" /></div><div><p className="text-sm font-bold text-[#765219]">Demo mode note</p><p className="mt-1 text-xs leading-5 text-[#977438]">Your clicks are live in this preview, but they do not reach Discord until you connect a server.</p></div></div></div></div></div></>;
}

function Shell() {
  const [location, setLocation] = useLocation();
  const [mobileOpen, setMobileOpen] = useState(false);
  const [balance, setBalance] = useState(12680);
  const [bank, setBank] = useState(8340);
  const [inventory, setInventory] = useState(seededInventory);
  const [activities, setActivities] = useState<ActivityItem[]>(seededActivity);
  const [dailyClaimed, setDailyClaimed] = useState(false);
  const [settings, setSettings] = useState<ServerSettings>({ prefix: '!', interest: 2.4, shopMarkup: 12, toggles: { daily: true, games: true, shop: true, memes: true } });
  const addActivity = (a: Omit<ActivityItem, 'id' | 'time'>) => setActivities(prev => [{ ...a, id: Date.now(), time: 'just now' }, ...prev]);
  const claimDaily = () => { if (dailyClaimed) return; setDailyClaimed(true); setBalance(balance + 250); addActivity({ type: 'earn', title: 'Daily reward claimed', detail: 'You kept the streak alive', amount: '+250 c' }); };
  const page = useMemo(() => location === '/' ? '/dashboard' : location, [location]);
  const onNav = (path: string) => setLocation(path);
  return <div className="noise app-shell bg-background"><Sidebar /><MobileNav open={mobileOpen} setOpen={setMobileOpen} /><main className="min-h-[100dvh] md:ml-[255px]"><div className="mx-auto max-w-[1440px] px-4 py-5 sm:px-7 sm:py-8 lg:px-10">{page === '/dashboard' && <Dashboard balance={balance} bank={bank} activities={activities} claimDaily={claimDaily} dailyClaimed={dailyClaimed} onNav={onNav} />}{page === '/economy' && <Economy balance={balance} bank={bank} setBalance={setBalance} setBank={setBank} inventory={inventory} setInventory={setInventory} addActivity={addActivity} />}{page === '/games' && <Games balance={balance} setBalance={setBalance} addActivity={addActivity} />}{page === '/meme-studio' && <MemeStudio addActivity={addActivity} />}{page === '/leaderboards' && <Leaderboards />}{page === '/moderation' && <Moderation activities={activities} addActivity={addActivity} />}{page === '/settings' && <Settings settings={settings} setSettings={setSettings} />}{page === '/help' && <Help />}</div></main></div>;
}

function App() {
  return <QueryClientProvider client={queryClient}><TooltipProvider><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, '')}><Switch><Route path="/" component={Shell} /><Route path="/dashboard" component={Shell} /><Route path="/economy" component={Shell} /><Route path="/games" component={Shell} /><Route path="/meme-studio" component={Shell} /><Route path="/leaderboards" component={Shell} /><Route path="/moderation" component={Shell} /><Route path="/settings" component={Shell} /><Route path="/help" component={Shell} /><Route><div className="flex min-h-screen items-center justify-center bg-background"><div className="text-center"><p className="font-display text-4xl font-bold">404</p><p className="mt-2 text-muted-foreground">That arcade cabinet is out of order.</p><Link href="/dashboard" className="mt-5 inline-block text-sm font-semibold text-primary">Return to command center</Link></div></div></Route></Switch></WouterRouter><Toaster /></TooltipProvider></QueryClientProvider>;
}

export default App;